using System.Collections.Generic;public class Solution{List<IList<string>>o=new();bool P(string s,int l,int r){while(l<r)if(s[l++]!=s[r--])return false;return true;}void F(string s,int st,List<string>v){if(st==s.Length){o.Add(new List<string>(v));return;}for(int e=st;e<s.Length;e++)if(P(s,st,e)){v.Add(s.Substring(st,e-st+1));F(s,e+1,v);v.RemoveAt(v.Count-1);}}public IList<IList<string>> Partition(string s){F(s,0,new List<string>());return o;}}
